mapper.select:
select menu_id, menu_name, parent_id, order_num, path, component, is_frame, is_cache, menu_type, visible, status, perms, icon, create_time from sys_menu where 1=1
AND menu_name like concat('%', #{menuName}, '%')
AND status = #{status}
AND visible = #{visible}
order by parent_id, order_num

select distinct m.menu_id, m.menu_name, m.parent_id, m.order_num, m.path, m.component, m.is_frame, m.is_cache, m.menu_type, m.visible, m.status, m.perms, m.icon, m.create_time
from sys_menu m
left join sys_role_menu rm on m.menu_id = rm.menu_id
left join sys_user_role ur on rm.role_id = ur.role_id
where ur.user_id = #{params.userId}

    AND m.menu_name like concat('%', #{menuName}, '%')


    AND m.status = #{status}


    AND m.visible = #{visible}

order by m.parent_id, m.order_num
